const { chromium } = require('C:/Users/paul/AppData/Roaming/npm/node_modules/playwright/index.js');

const BODY_HTML = `<p style="text-align: center; line-height: 1.6;">💭 "클린트만 5번 돌렸는데 마음에 안 든다고?"<br>💭 "수정 요청 30회, 편집자가 연락 두절"<br>💭 "이번 달 편집자, 또 바꿔야 하나?"</p><p style="text-align: center;"><br></p><p style="text-align: center; line-height: 1.6;">영상 편집 아웃소싱을 해본 브랜드라면<br>누구나 한 번쯤 겪는 상황입니다.</p><p style="text-align: center;"><br></p><p style="text-align: center;"><img src="https://postfiles.pstatic.net/MjAyNTA2MjBfMjY4/MDAxNzUwNDA5MzYyNzM2.2h1mFaqyMKBmk6STUFYmBHovZjj4bPkIXSyA27_cnFsg.PNG.genie0705/aicut_blog_freelancer_01.png?type=w773" alt="프리랜서 편집러 문제 상황" style="max-width: 100%;"></p><h2 style="text-align: center; font-size: 22px; margin-top: 40px; margin-bottom: 20px;">😤 프리랜서 편집러, 왜 자꾸 바꾸게 될까?</h2><p style="text-align: center; line-height: 1.6;"><strong>영상 편집 프리랜서</strong>를 고용해본 분들은<br>다음 같은 경험을 해보셨을 겁니다.</p><p style="text-align: center;"><br></p><h3 style="text-align: center; font-size: 18px; margin-top: 30px;">① 클린트 무한 반복</h3><p style="text-align: center; line-height: 1.6;">"자막이 좀 더 세련되게"<br>"배경 음악이 안 맞는 것 같아요"<br>"컬러 톤을 좀 더 따뜻하게"</p><p style="text-align: center; line-height: 1.6;">매번 다른 의견, 매번 다른 결과.<br><strong>클린트</strong> 5번 돌려도 원하는 느낌이 안 나오는 건<br>편집자의 문제가 아니라 <strong>시스템의 문제</strong>입니다.</p><p style="text-align: center;"><br></p><h3 style="text-align: center; font-size: 18px; margin-top: 30px;">② 매달 새로운 편집자 찾기</h3><p style="text-align: center; line-height: 1.6;">이번 달 A라는 편집자가 괜찮아서<br>다음 달에도 맡기려고 했는데,<br>이미 다른 프로젝트에 잡혀 있습니다.</p><p style="text-align: center; line-height: 1.6;">또 구인 공고를 내고,<br>또 포트폴리오를 보고,<br>또 교육하고. 이 과정이 매달 반복됩니다.</p><p style="text-align: center;"><br></p><h3 style="text-align: center; font-size: 18px; margin-top: 30px;">③ 소통 비용 &gt; 편집 비용</h3><p style="text-align: center; line-height: 1.6;">"A 편집자님, 저번에 말씀드린 대로..."<br>"아, 그건 전달이 안 됐네요? 다시 확인해볼게요."</p><p style="text-align: center; line-height: 1.6;"><strong>편집자와의 소통</strong>에 들어가는 시간이<br>실제 편집 비용보다 더 큽니다.</p><p style="text-align: center;"><br></p><p style="text-align: center;"><img src="https://postfiles.pstatic.net/MjAyNTA2MjBfMTUy/MDAxNzUwNDA5MzYyNzM2.cQKnw9l66PLWBCNq7q8l8MqGyM56-J2N8XGZJ-k6q9wg.PNG.genie0705/aicut_blog_freelancer_02.png?type=w773" alt="에이컷 전담 에디터 시스템" style="max-width: 100%;"></p><h2 style="text-align: center; font-size: 22px; margin-top: 40px; margin-bottom: 20px;">💡 에이컷이 해결한 방법 (전담 에디터 시스템)</h2><p style="text-align: center; line-height: 1.6;">에이컷은 프리랜서 편집러의 문제를<br><strong>시스템으로 해결</strong>했습니다.</p><p style="text-align: center;"><br></p><h3 style="text-align: center; font-size: 18px; margin-top: 30px;">👤 전담 에디터 고정 배정</h3><p style="text-align: center; line-height: 1.6;">한 번 배정된 에디터는<br>변경 요청이 없는 한 계속 같은 분이 작업합니다.</p><p style="text-align: center;"><br></p><h3 style="text-align: center; font-size: 18px; margin-top: 30px;">📋 브랜드 가이드 저장</h3><p style="text-align: center; line-height: 1.6;">색상 코드, 로고 위치, 자막 폰트, BGM 방향성까지<br>한 번 등록하면 다음 작업부터 설명이 필요 없습니다.</p><p style="text-align: center;"><br></p><h3 style="text-align: center; font-size: 18px; margin-top: 30px;">⚡ 48시간 기본 납기</h3><p style="text-align: center; line-height: 1.6;">브랜드에 맞는 편집 스타일이 이미 저장되어 있어<br>리드타임이 획기적으로 줄어듭니다.</p><p style="text-align: center;"><br></p><p style="text-align: center;"><img src="https://postfiles.pstatic.net/MjAyNTA2MjBfMjY1/MDAxNzUwNDA5MzYyNzM3.-n1jytgwG1n3ZQTRh3MUw7xxP6wRRvkCDL6qjLFeJg8g.PNG.genie0705/aicut_blog_freelancer_03.png?type=w773" alt="에이컷 도입 전후 비교" style="max-width: 100%;"></p><h2 style="text-align: center; font-size: 22px; margin-top: 40px; margin-bottom: 20px;">📊 바뀐 결과</h2><p style="text-align: center; line-height: 1.6;">에이컷 도입 후 고객사들의 변화입니다.</p><p style="text-align: center;"><br></p><div style="text-align: center;"><table style="margin: 0 auto; border-collapse: collapse; width: 100%; max-width: 500px;"><tbody><tr><th style="background: #a78bfa; color: #fff; padding: 10px;">항목</th><th style="background: #a78bfa; color: #fff; padding: 10px;">도입 전</th><th style="background: #a78bfa; color: #fff; padding: 10px;">도입 후</th></tr><tr><td style="padding: 10px; border-bottom: 1px solid #eee;"><strong>편집자 교체 주기</strong></td><td style="padding: 10px; border-bottom: 1px solid #eee; text-align: center; color: #cc4444;">매월</td><td style="padding: 10px; border-bottom: 1px solid #eee; text-align: center; color: #22aa66; font-weight: 700;">고정 배정</td></tr><tr><td style="padding: 10px; border-bottom: 1px solid #eee;"><strong>클린트 평균 횟수</strong></td><td style="padding: 10px; border-bottom: 1px solid #eee; text-align: center; color: #cc4444;">5~7회</td><td style="padding: 10px; border-bottom: 1px solid #eee; text-align: center; color: #22aa66; font-weight: 700;">1~2회</td></tr><tr><td style="padding: 10px; border-bottom: 1px solid #eee;"><strong>커뮤니케이션 시간</strong></td><td style="padding: 10px; border-bottom: 1px solid #eee; text-align: center; color: #cc4444;">주 8시간</td><td style="padding: 10px; border-bottom: 1px solid #eee; text-align: center; color: #22aa66; font-weight: 700;">주 1시간 이내</td></tr><tr><td style="padding: 10px;"><strong>납기 준수율</strong></td><td style="padding: 10px; text-align: center; color: #cc4444;">60%</td><td style="padding: 10px; text-align: center; color: #22aa66; font-weight: 700;">98%</td></tr></tbody></table></div><p style="text-align: center;"><br></p><p style="text-align: center;"><img src="https://postfiles.pstatic.net/MjAyNTA2MjBfMjEy/MDAxNzUwNDA5MzYyNzM3.eV7TeVYQWYVUs4BuCk_ts2tIhiT_CBeNbQ0ahYoI04cg.PNG.genie0705/aicut_blog_freelancer_cta.png?type=w773" alt="에이컷 무료 상담" style="max-width: 100%;"></p><h2 style="text-align: center; font-size: 22px; margin-top: 40px; margin-bottom: 20px;">🎯 이런 분들께 특히 추천합니다</h2><p style="text-align: center; line-height: 1.6;">매달 다른 편집자에게 브랜드를 설명해야 하는 분<br>클린트 피드백에 지친 마케터<br>납기 지연으로 광고 일정이 밀리는 분<br>브랜드 톤 일관성이 중요한 기업</p><p style="text-align: center;"><br></p><h2 style="text-align: center; font-size: 22px; margin-top: 40px; margin-bottom: 20px;">👀 지금 확인해보세요</h2><p style="text-align: center; line-height: 1.6;">프리랜서 편집러와의 끝없는 소통,<br>이제는 시스템에 맡기세요.</p><p style="text-align: center; line-height: 1.6;"><strong>에이컷 무료 상담</strong>에서<br>업종과 월 제작량에 맞는 플랜을<br>전담 매니저가 직접 안내해드립니다.</p><p style="text-align: center;"><br></p><p style="text-align: center; line-height: 1.8;">👉 <strong>카카오톡 채널:</strong> 에이컷<br>👉 <strong>이메일:</strong> contact@aicut.co.kr<br>👉 <strong>홈페이지:</strong> aicut.co.kr</p>`;

const HASHTAGS = "#영상편집외주 #프리랜서편집 #영상편집대행 #에이컷 #AICUT #전담에디터 #48시간납품 #영상편집 #숏폼제작 #릴스편집 #영상제작 #콘텐츠마케팅 #영상마케팅 #SNS영상 #마케팅영상 #브랜드영상 #편집외주 #영상편집비용 #영상편집서비스 #영상편집월정액 #클린트 #수정요청 #브랜드가이드 #전담매니저 #숏폼마케팅 #유튜브편집 #쇼츠제작 #인스타릴스 #영상편집전문 #콘텐츠제작";

(async () => {
  const browser = await chromium.connectOverCDP('http://127.0.0.1:9223');
  const ctx = browser.contexts()[0];
  const page = await ctx.newPage();
  
  // Open blog editor
  console.log('=== 에디터 열기 ===');
  await page.goto('https://blog.naver.com/PostWriteForm.naver?blogId=aicut', { waitUntil: 'networkidle', timeout: 30000 });
  await page.waitForTimeout(5000);
  
  // 1. Set title
  console.log('\n=== 제목 입력 ===');
  await page.evaluate(() => {
    SmartEditor._editors['blogpc001'].setDocumentTitle('영상편집 클린트 5번, 수정 요청 30회... 프리랜서 편집러와 작별한 이유');
  });
  console.log('✅ 제목 입력 완료');
  await page.waitForTimeout(1000);
  
  // 2. Upload 5 images
  console.log('\n=== 이미지 업로드 ===');
  const IMAGE_FILES = [
    'aicut_blog_freelancer_thumb.png',
    'aicut_blog_freelancer_01.png',
    'aicut_blog_freelancer_02.png',
    'aicut_blog_freelancer_03.png',
    'aicut_blog_freelancer_cta.png',
  ];
  
  for (let i = 0; i < IMAGE_FILES.length; i++) {
    const imgPath = 'C:\\Users\\paul\\.openclaw\\workspace\\' + IMAGE_FILES[i];
    console.log(`  ${i+1}/5: ${IMAGE_FILES[i]}`);
    
    const fcPromise = page.waitForEvent('filechooser', { timeout: 10000 });
    await page.click('button.se-image-toolbar-button');
    const fc = await fcPromise.catch(() => null);
    
    if (fc) {
      await fc.setFiles(imgPath);
      await page.waitForTimeout(2000);
      console.log(`  ✅ 업로드 완료`);
    } else {
      console.log(`  ❌ 실패`);
    }
  }
  
  // 3. Paste body content via clipboard
  console.log('\n=== 본문 붙여넣기 ===');
  await page.evaluate((html) => {
    navigator.clipboard.writeText(html);
  }, BODY_HTML);
  
  await page.waitForTimeout(500);
  
  // Find and click on the editor content area
  const editorClicked = await page.evaluate(() => {
    try {
      const editor = SmartEditor._editors['blogpc001'];
      if (editor && editor.getEditor) {
        const ed = editor.getEditor();
        if (ed && ed.focus) {
          ed.focus();
          return 'focus() called';
        }
      }
      return 'focus not available';
    } catch(e) { return 'Error: ' + e.message; }
  });
  console.log('Editor focus:', editorClicked);
  
  await page.waitForTimeout(500);
  
  // Use keyboard to paste
  await page.keyboard.press('Control+v');
  await page.waitForTimeout(3000);
  console.log('✅ 본문 붙여넣기 완료');
  
  // 4. Add hashtags
  console.log('\n=== 해시태그 입력 ===');
  // Find the hashtag input
  await page.evaluate((tags) => {
    // Try to find tag input
    const inputs = document.querySelectorAll('input');
    for (const input of inputs) {
      const ph = (input.placeholder || '').toLowerCase();
      if (ph.includes('태그') || ph.includes('tag')) {
        input.value = '';
        // Set native input value
        const nativeInputValueSetter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
        nativeInputValueSetter.call(input, tags);
        input.dispatchEvent(new Event('input', { bubbles: true }));
        input.dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', bubbles: true }));
        return '태그 입력 완료 via input';
      }
    }
    return '태그 input not found';
  }, HASHTAGS);
  await page.waitForTimeout(2000);
  
  // 5. Final screenshot
  await page.screenshot({ path: 'C:\\Users\\paul\\.openclaw\\workspace\\blog_done_final.png', fullPage: true });
  
  console.log('\n=== 🎉 블로그 포스팅 거의 완료 ===');
  console.log('✅ 제목: 입력됨');
  console.log('✅ 이미지 5장: 업로드됨');
  console.log('✅ 본문: 붙여넣기 완료');
  console.log('✅ 해시태그: 입력 시도');
  console.log('');
  console.log('📌 남은 작업 (정이사님이 직접):');
  console.log('1. 에디터 화면 확인');
  console.log('2. 저장 or 발행 버튼 클릭');
  
  await browser.close();
})();
